SUPPORTED_LANGUAGES = [
    "English", "Kiswahili", "Sheng", "Kikuyu (Gikuyu)", "Kamba (Kikamba)", 
    "Kalenjin", "Luo (Dholuo)", "Luhya", "Meru (Kimeru)", "Kisii (Ekegusii)", 
    "Somali", "Maasai (Maa)", "Turkana", "Kuria (Ekikuria)", "Teso (Ateso)", 
    "Mijikenda (Giriama/Digo)", "Taita (Kitaita)", "Embu (Kiembu)", "Tharaka", 
    "Pokot", "Borana (Oromo)", "Suba", "Nubian (Kinubi)", "Samburu", 
    "Rendille", "Gabra", "Orma", "Chuka", "Mbeere", "Nyole", 
    "Terik", "Ogiek", "Sengwer", "Ilchamus", "Boni", "Dahalo", 
    "Yaaku", "Engsh", "Bajuni", "Swahili (Coastal)", "Taveta", "Malakote", "Sanye"
]

class TranslationRegistry:
    def __init__(self, base_dict, all_langs):
        self.registry = base_dict
        for lang in all_langs:
            if lang not in self.registry:
                self.registry[lang] = self.registry["English"]

TRANSLATIONS = TranslationRegistry(BASE_TRANSLATIONS, SUPPORTED_LANGUAGES).registry

def get_translation(lang: str, key: str) -> str:
    if lang in TRANSLATIONS and key in TRANSLATIONS[lang]:
        return TRANSLATIONS[lang][key]
    return TRANSLATIONS["English"].get(key, key)